@page "/book-appointment"
@rendermode InteractiveServer
@using sv_f6693d403751455b846281e0abb06e13.Services
@using System.ComponentModel.DataAnnotations
@inject AppointmentService AppointmentService

<h1>Book Appointment</h1>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="book-appointment">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <h2>Step 1: Patient Information</h2>

    <div>
        <label>
            Patient Name:
            <InputText @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </label>
    </div>

    <div>
        <label>
            Email:
            <InputText @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </label>
    </div>

    <div>
        <label>
            Phone:
            <InputText @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </label>
    </div>

    <div>
        <label>
            Insurance Provider:
            <InputSelect @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </label>
    </div>

    @if (!showStep2)
    {
        <button type="button" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <h2>Step 2: Appointment Details</h2>

        <div>
            <label>
                Preferred Doctor:
                <InputSelect @bind-Value="model.Doctor" @bind:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doctor in doctors)
                    {
                        <option value="@doctor">@doctor</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.Doctor" />
            </label>
        </div>

        <div>
            <label>
                Date:
                <InputDate @bind-Value="model.AppointmentDate" @bind:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
            </label>
        </div>

        <div>
            <label>
                Time Slot:
                <InputSelect @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </label>
        </div>

        <div>
            <label>
                Reason for Visit:
                <InputTextArea @bind-Value="model.ReasonForVisit" />
                <ValidationMessage For="() => model.ReasonForVisit" />
            </label>
        </div>

        <button type="button" @onclick="CheckAvailability" disabled="@isSubmitting">
            @(isSubmitting ? "Checking..." : "Check Availability")
        </button>

        @if (bookingConfirmed)
        {
            <p><strong>Appointment booked successfully!</strong></p>
        }
    }
</EditForm>

@code {
    private EditContext? editContext;
    private AppointmentModel model = new();
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isSubmitting;
    private bool bookingConfirmed;

    private List<string> doctors = new();
    private List<string> timeSlots = new();

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        customValidator?.ClearErrors();

        // Validate only step 1 fields
        var isValid = true;
        var step1Fields = new[] {
            nameof(AppointmentModel.PatientName),
            nameof(AppointmentModel.Email),
            nameof(AppointmentModel.Phone),
            nameof(AppointmentModel.InsuranceProvider)
        };

        // Trigger full validation to populate messages, then check step 1 fields
        editContext!.Validate();
        foreach (var field in step1Fields)
        {
            var fieldIdentifier = editContext.Field(field);
            if (editContext.GetValidationMessages(fieldIdentifier).Any())
            {
                isValid = false;
            }
        }

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();

        if (!editContext!.Validate())
            return;

        isSubmitting = true;
        try
        {
            var errors = await AppointmentService.ValidatePatientAsync(
                model.Email!,
                model.InsuranceProvider!,
                model.Doctor!,
                model.TimeSlot!);

            if (errors.Count > 0)
            {
                // Map service field names to model field names
                var mappedErrors = new Dictionary<string, List<string>>();
                foreach (var (key, value) in errors)
                {
                    var modelField = key switch
                    {
                        "email" => nameof(AppointmentModel.Email),
                        "doctor" => nameof(AppointmentModel.Doctor),
                        "timeSlot" => nameof(AppointmentModel.TimeSlot),
                        _ => key
                    };
                    mappedErrors[modelField] = value;
                }
                customValidator!.DisplayErrors(mappedErrors);
                return;
            }

            bookingConfirmed = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private Task HandleSubmit()
    {
        // Form-level submit (Enter key) — route through CheckAvailability
        return CheckAvailability();
    }

    public class AppointmentModel
    {
        [Required(ErrorMessage = "Patient name is required.")]
        public string? PatientName { get; set; }

        [Required(ErrorMessage = "Email is required.")]
        [EmailAddress(ErrorMessage = "Invalid email format.")]
        public string? Email { get; set; }

        [Required(ErrorMessage = "Phone is required.")]
        public string? Phone { get; set; }

        [Required(ErrorMessage = "Insurance provider is required.")]
        public string? InsuranceProvider { get; set; }

        [Required(ErrorMessage = "Doctor is required.")]
        public string? Doctor { get; set; }

        [Required(ErrorMessage = "Date is required.")]
        [FutureDate(ErrorMessage = "Date must be in the future.")]
        public DateTime? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Time slot is required.")]
        public string? TimeSlot { get; set; }

        [Required(ErrorMessage = "Reason for visit is required.")]
        [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters.")]
        public string? ReasonForVisit { get; set; }
    }

    public class FutureDateAttribute : ValidationAttribute
    {
        protected override ValidationResult? IsValid(object? value, ValidationContext context)
        {
            if (value is DateTime date && date.Date <= DateTime.Today)
            {
                return new ValidationResult(ErrorMessage);
            }
            return ValidationResult.Success;
        }
    }
}

